import {
    createContext,
    useCallback,
    useContext,
    useEffect,
    useId,
    useMemo,
    useRef,
    useState,
} from 'react';
import type { ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import { Kbd, KbdGroup } from '@/components/ui/kbd';
import {
    RESERVED_SHORTCUTS,
    isSingleKeyShortcut,
    isTypingTarget,
    matchesShortcut,
    shortcutKeyCaps,
} from '@/lib/shortcut-keys';

/**
 * Keyboard shortcuts for the qiick apps (optional pattern
 * `keyboard-shortcuts`, docs/optional/keyboard-shortcuts.md).
 *
 * One document listener dispatches every shortcut a mounted component
 * registers with `useShortcut`, so shortcuts are scoped by what is on screen:
 * a list registers `j` / `k` while it is mounted, and the most recently
 * mounted registration of the same keys wins (a page over the shell).
 *
 * Rules the listener enforces, so no screen has to:
 * - a key press another handler already took (`defaultPrevented`, e.g. ⌘K
 *   inside a rich-text editor that inserts a link) is left alone;
 * - single-key shortcuts never fire while the person types, and not at all
 *   when the user turned them off (WCAG 2.1.4);
 * - modifier shortcuts fire in plain fields, but not inside a rich-text editor.
 *
 * `?` opens the help dialog listing every active shortcut.
 */

type ShortcutRegistration = {
    id: string;
    keys: string;
    description: string;
    group: string;
    handler: (event: KeyboardEvent) => void;
};

type ShortcutsContextValue = {
    register: (registration: ShortcutRegistration) => () => void;
    registrations: ShortcutRegistration[];
    isApplePlatform: boolean;
};

const ShortcutsContext = createContext<ShortcutsContextValue | null>(null);

/** `mod` means ⌘ on Apple platforms and Ctrl elsewhere. */
function detectApplePlatform(): boolean {
    if (typeof navigator === 'undefined') {
        return false;
    }

    return /mac|iphone|ipad|ipod/i.test(navigator.userAgent);
}

type ShortcutsProviderProps = {
    children: ReactNode;
    /**
     * The user's setting: false turns off every single-key shortcut (`j`,
     * `e`, `?`); ⌘ / Ctrl shortcuts keep working.
     */
    canUseSingleKeyShortcuts?: boolean;
};

/**
 * Wrap the authenticated app once (next to `TooltipProvider`).
 */
export function ShortcutsProvider({
    children,
    canUseSingleKeyShortcuts = true,
}: ShortcutsProviderProps) {
    const [registrations, setRegistrations] = useState<ShortcutRegistration[]>(
        [],
    );
    const registrationsRef = useRef<ShortcutRegistration[]>([]);
    const [isHelpOpen, setIsHelpOpen] = useState(false);
    const isApplePlatform = useMemo(() => detectApplePlatform(), []);

    const register = useCallback((registration: ShortcutRegistration) => {
        registrationsRef.current = [
            ...registrationsRef.current.filter(
                (existing) => existing.id !== registration.id,
            ),
            registration,
        ];
        setRegistrations(registrationsRef.current);

        return () => {
            registrationsRef.current = registrationsRef.current.filter(
                (existing) => existing.id !== registration.id,
            );
            setRegistrations(registrationsRef.current);
        };
    }, []);

    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.defaultPrevented || event.isComposing) {
                return;
            }

            const isTyping = isTypingTarget(event.target);
            const isInEditor =
                event.target instanceof HTMLElement &&
                event.target.isContentEditable;
            const candidates = [...registrationsRef.current].reverse();

            for (const registration of candidates) {
                if (
                    !matchesShortcut(event, registration.keys, isApplePlatform)
                ) {
                    continue;
                }

                if (isSingleKeyShortcut(registration.keys)) {
                    if (!canUseSingleKeyShortcuts || isTyping) {
                        return;
                    }
                } else if (isInEditor) {
                    return;
                }

                event.preventDefault();
                registration.handler(event);

                return;
            }
        };

        document.addEventListener('keydown', handleKeyDown);

        return () => document.removeEventListener('keydown', handleKeyDown);
    }, [canUseSingleKeyShortcuts, isApplePlatform]);

    const contextValue = useMemo(
        () => ({ register, registrations, isApplePlatform }),
        [register, registrations, isApplePlatform],
    );

    return (
        <ShortcutsContext.Provider value={contextValue}>
            <HelpShortcut onOpen={() => setIsHelpOpen(true)} />
            {children}
            <ShortcutsHelpDialog
                open={isHelpOpen}
                onOpenChange={setIsHelpOpen}
                canUseSingleKeyShortcuts={canUseSingleKeyShortcuts}
            />
        </ShortcutsContext.Provider>
    );
}

function useShortcutsContext(): ShortcutsContextValue {
    const contextValue = useContext(ShortcutsContext);

    if (!contextValue) {
        throw new Error('useShortcut needs a ShortcutsProvider above it.');
    }

    return contextValue;
}

type UseShortcutOptions = {
    /** `mod+k`, `shift+?`, `j`: see `lib/shortcut-keys.ts`. */
    keys: string;
    /** Shown in the help dialog, already translated. */
    description: string;
    /** Help dialog section, already translated (e.g. "Navigation", "List"). */
    group: string;
    handler: (event: KeyboardEvent) => void;
    /** False keeps the shortcut out while, say, a list has no rows. */
    isEnabled?: boolean;
};

/**
 * Registers a shortcut while the calling component is mounted. The handler
 * may change on every render: the latest one runs.
 */
export function useShortcut({
    keys,
    description,
    group,
    handler,
    isEnabled = true,
}: UseShortcutOptions): void {
    const { register } = useShortcutsContext();
    const id = useId();
    const handlerRef = useRef(handler);

    useEffect(() => {
        handlerRef.current = handler;
    });

    useEffect(() => {
        if (!isEnabled) {
            return;
        }

        return register({
            id,
            keys,
            description,
            group,
            handler: (event) => handlerRef.current(event),
        });
    }, [register, id, keys, description, group, isEnabled]);
}

/** The key caps of a definition on this platform, for hints next to a control. */
export function useShortcutKeyCaps(keys: string): string[] {
    const { isApplePlatform } = useShortcutsContext();

    return useMemo(
        () => shortcutKeyCaps(keys, isApplePlatform),
        [keys, isApplePlatform],
    );
}

/** A shortcut hint (`⌘ K`) next to a control or in a tooltip. */
export function ShortcutHint({
    keys,
    className,
}: {
    keys: string;
    className?: string;
}) {
    const keyCaps = useShortcutKeyCaps(keys);

    return (
        <KbdGroup className={className} aria-hidden="true">
            {keyCaps.map((keyCap) => (
                <Kbd key={keyCap}>{keyCap}</Kbd>
            ))}
        </KbdGroup>
    );
}

function HelpShortcut({ onOpen }: { onOpen: () => void }) {
    const { t } = useTranslation();

    useShortcut({
        keys: RESERVED_SHORTCUTS.shortcutsHelp,
        description: t('shortcuts.showHelp'),
        group: t('shortcuts.groupGeneral'),
        handler: onOpen,
    });

    return null;
}

type ShortcutsHelpDialogProps = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    canUseSingleKeyShortcuts: boolean;
};

/**
 * Lists the shortcuts active on this screen, by group. Opened with `?`.
 */
function ShortcutsHelpDialog({
    open,
    onOpenChange,
    canUseSingleKeyShortcuts,
}: ShortcutsHelpDialogProps) {
    const { t } = useTranslation();
    const { registrations, isApplePlatform } = useShortcutsContext();
    const registrationsByGroup = useMemo(() => {
        const groups = new Map<string, ShortcutRegistration[]>();
        const seenKeys = new Set<string>();

        // The latest registration of a key is the one that fires.
        for (const registration of [...registrations].reverse()) {
            if (seenKeys.has(registration.keys)) {
                continue;
            }

            if (
                !canUseSingleKeyShortcuts &&
                isSingleKeyShortcut(registration.keys)
            ) {
                continue;
            }

            seenKeys.add(registration.keys);
            groups.set(registration.group, [
                ...(groups.get(registration.group) ?? []),
                registration,
            ]);
        }

        return [...groups.entries()].reverse();
    }, [registrations, canUseSingleKeyShortcuts]);

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-md">
                <DialogHeader>
                    <DialogTitle>{t('shortcuts.title')}</DialogTitle>
                    <DialogDescription>
                        {canUseSingleKeyShortcuts
                            ? t('shortcuts.description')
                            : t('shortcuts.singleKeyOff')}
                    </DialogDescription>
                </DialogHeader>
                <div className="grid gap-4">
                    {registrationsByGroup.map(([group, groupRegistrations]) => (
                        <section key={group} className="grid gap-2">
                            <h3 className="text-xs font-medium text-muted-foreground">
                                {group}
                            </h3>
                            <dl className="grid gap-1.5">
                                {[...groupRegistrations]
                                    .reverse()
                                    .map((registration) => (
                                        <div
                                            key={registration.id}
                                            className="flex items-center justify-between gap-4 text-sm"
                                        >
                                            <dt>{registration.description}</dt>
                                            <dd>
                                                <KbdGroup>
                                                    {shortcutKeyCaps(
                                                        registration.keys,
                                                        isApplePlatform,
                                                    ).map((keyCap) => (
                                                        <Kbd key={keyCap}>
                                                            {keyCap}
                                                        </Kbd>
                                                    ))}
                                                </KbdGroup>
                                            </dd>
                                        </div>
                                    ))}
                            </dl>
                        </section>
                    ))}
                </div>
            </DialogContent>
        </Dialog>
    );
}

/**
 * Keyboard shortcut definitions as plain strings (`mod+k`, `shift+?`, `j`), and
 * the pure logic that matches them against a `KeyboardEvent`. It has no React
 * and no imports, so scripts can test it directly.
 *
 * `mod` is ⌘ on Apple platforms and Ctrl elsewhere, so a definition is written
 * once for every platform.
 */

/** Modifier names a definition may combine with one key. */
const MODIFIERS = ['mod', 'ctrl', 'alt', 'shift'] as const;

type ShortcutModifier = (typeof MODIFIERS)[number];

export type ParsedShortcut = {
    modifiers: Set<ShortcutModifier>;
    key: string;
};

/**
 * Shortcuts the qiick apps reserve for shared features. An app never binds
 * them to anything else, so the command palette and the Assistant panel open
 * the same way in every product.
 */
export const RESERVED_SHORTCUTS = {
    commandPalette: 'mod+k',
    assistantPanel: 'mod+j',
    shortcutsHelp: 'shift+?',
} as const;

/**
 * @param definition - `mod+k`, `shift+?`, `j`
 * @throws {Error} When a part is not a known modifier or there is no key
 */
export function parseShortcut(definition: string): ParsedShortcut {
    const parts = definition.toLowerCase().split('+');
    const key = parts.pop();

    if (!key) {
        throw new Error(`Shortcut "${definition}" has no key.`);
    }

    const modifiers = new Set<ShortcutModifier>();

    for (const part of parts) {
        if (!MODIFIERS.includes(part as ShortcutModifier)) {
            throw new Error(
                `Shortcut "${definition}": "${part}" is not a modifier.`,
            );
        }

        modifiers.add(part as ShortcutModifier);
    }

    return { modifiers, key };
}

/**
 * A single-key shortcut fires without ⌘ / Ctrl / Alt (Shift alone still
 * counts). Users can turn these off (WCAG 2.1.4), and they never fire while
 * the person types in a field.
 */
export function isSingleKeyShortcut(definition: string): boolean {
    const { modifiers } = parseShortcut(definition);

    return (
        !modifiers.has('mod') && !modifiers.has('ctrl') && !modifiers.has('alt')
    );
}

type ShortcutKeyEvent = Pick<
    KeyboardEvent,
    'key' | 'metaKey' | 'ctrlKey' | 'altKey' | 'shiftKey'
>;

/**
 * @param isApplePlatform - Whether `mod` means ⌘ (metaKey) rather than Ctrl
 */
export function matchesShortcut(
    event: ShortcutKeyEvent,
    definition: string,
    isApplePlatform: boolean,
): boolean {
    const { modifiers, key } = parseShortcut(definition);
    const shouldPressMeta = isApplePlatform && modifiers.has('mod');
    const shouldPressCtrl =
        modifiers.has('ctrl') || (!isApplePlatform && modifiers.has('mod'));

    if (
        event.metaKey !== shouldPressMeta ||
        event.ctrlKey !== shouldPressCtrl
    ) {
        return false;
    }

    if (event.altKey !== modifiers.has('alt')) {
        return false;
    }

    // Shift changes the printed key ("?" is Shift+/), so a definition that names
    // the printed key only requires Shift when it says so.
    if (modifiers.has('shift') && !event.shiftKey) {
        return false;
    }

    return event.key.toLowerCase() === key;
}

/**
 * The key caps to show for a definition: `['⌘', 'K']` on Apple platforms,
 * `['Ctrl', 'K']` elsewhere. Shift is dropped when the key is already a
 * shifted symbol (`shift+?` shows `?`).
 */
export function shortcutKeyCaps(
    definition: string,
    isApplePlatform: boolean,
): string[] {
    const { modifiers, key } = parseShortcut(definition);
    const isShiftedSymbol = key.length === 1 && !/[a-z0-9]/.test(key);
    const keyCaps: string[] = [];

    if (modifiers.has('mod')) {
        keyCaps.push(isApplePlatform ? '⌘' : 'Ctrl');
    }

    if (modifiers.has('ctrl')) {
        keyCaps.push(isApplePlatform ? '⌃' : 'Ctrl');
    }

    if (modifiers.has('alt')) {
        keyCaps.push(isApplePlatform ? '⌥' : 'Alt');
    }

    if (modifiers.has('shift') && !isShiftedSymbol) {
        keyCaps.push(isApplePlatform ? '⇧' : 'Shift');
    }

    keyCaps.push(key.length === 1 ? key.toUpperCase() : key);

    return keyCaps;
}

/**
 * Whether a key press comes from a place where the person is typing: a text
 * field, a select, or a rich-text editor (contenteditable). Single-key
 * shortcuts never fire there.
 */
export function isTypingTarget(target: EventTarget | null): boolean {
    if (!target || typeof (target as Element).closest !== 'function') {
        return false;
    }

    const element = target as HTMLElement;

    if (element.isContentEditable) {
        return true;
    }

    return (
        element.closest(
            'input:not([type=checkbox]):not([type=radio]):not([type=button]):not([type=submit]), textarea, select, [contenteditable=""], [contenteditable=true]',
        ) !== null
    );
}
